<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$pageTitle='Audit Logs';$activeMenu='audit';$rows=db()->query("SELECT a.*,COALESCE(CONCAT(u.first_name,' ',u.last_name),'System/Guest') actor FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 3000")->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Audit Logs</h1><p>Immutable activity trail for authentication, CRUD, approvals, uploads and report exports.</p></div><button class="btn btn-light border no-print" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Print</button></div><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Date & Time</th><th>User</th><th>Action</th><th>Module</th><th>Description</th><th>IP Address</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M d, Y h:i:s A',strtotime($r['created_at'])))?></td><td><?=e($r['actor'])?></td><td><span class="badge bg-light text-dark border"><?=e($r['action'])?></span></td><td><?=e($r['module'])?></td><td><?=e($r['description'])?></td><td><code><?=e($r['ip_address'])?></code></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
